import React, { useState } from 'react';
import { useWeb3React } from '@web3-react/core';
import { ethers } from 'ethers';
import {
  Box,
  Paper,
  Typography,
  TextField,
  Button,
  Alert,
  Tabs,
  Tab,
} from '@mui/material';
import { injected } from '../connectors';
import SupplyChain from '../abi/SupplyChain.json';
// require("dotenv").config();


const PRODUCT_REVIEW_ADDRESS = "0xb879c6DDF2d45667d796Fe917398C31C79A64c8E"; // Thay thế bằng địa chỉ contract sau khi deploy
const PRODUCT_REVIEW_ABI = SupplyChain.abi; 

function TabPanel(props) {
  const { children, value, index, ...other } = props;
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      {...other}
    >
      {value === index && (
        <Box sx={{ p: 3 }}>
          {children}
        </Box>
      )}
    </div>
  );
}

function Login() {
  const { active, account, activate, deactivate } = useWeb3React();
  const [tabValue, setTabValue] = useState(0);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const connect = async () => {
    try {
      await activate(injected);
    } catch (error) {
      setError('Lỗi kết nối ví: ' + error.message);
    }
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    if (!active) {
      setError('Vui lòng kết nối ví trước');
      return;
    }

    try {
      const provider = new ethers.providers.Web3Provider(window.ethereum);
      const contract = new ethers.Contract(
        PRODUCT_REVIEW_ADDRESS,
        PRODUCT_REVIEW_ABI,
        provider
      );

      const isValid = await contract.login(username, password);
      if (isValid) {
        setSuccess('Đăng nhập thành công!');
        // Có thể thêm logic chuyển hướng hoặc lưu trạng thái đăng nhập ở đây
      } else {
        setError('Tên đăng nhập hoặc mật khẩu không chính xác');
      }
    } catch (error) {
      setError('Lỗi đăng nhập: ' + error.message);
    }
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    if (!active) {
      setError('Vui lòng kết nối ví trước');
      return;
    }

    try {
      const provider = new ethers.providers.Web3Provider(window.ethereum);
      const signer = provider.getSigner();
      const contract = new ethers.Contract(
        PRODUCT_REVIEW_ADDRESS,
        PRODUCT_REVIEW_ABI,
        signer
      );

      const tx = await contract.registerUser(username, password);
      await tx.wait();
      setSuccess('Đăng ký thành công!');
      setUsername('');
      setPassword('');
      setTabValue(0); // Chuyển về tab đăng nhập
    } catch (error) {
      setError('Lỗi đăng ký: ' + error.message);
    }
  };

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
    setError('');
    setSuccess('');
  };

  return (
    <Paper sx={{ p: 3, maxWidth: 400, mx: 'auto', mt: 4 }}>
      <Typography variant="h5" gutterBottom align="center">
        Đăng Nhập / Đăng Ký
      </Typography>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}
      {success && (
        <Alert severity="success" sx={{ mb: 2 }}>
          {success}
        </Alert>
      )}

      {!active ? (
        <Button
          variant="contained"
          color="primary"
          fullWidth
          onClick={connect}
        >
          Kết Nối Ví
        </Button>
      ) : (
        <>
          <Typography variant="body2" gutterBottom align="center">
            Đã kết nối: {account}
          </Typography>
          <Button
            variant="outlined"
            color="secondary"
            fullWidth
            onClick={deactivate}
            sx={{ mb: 2 }}
          >
            Ngắt Kết Nối
          </Button>

          <Tabs value={tabValue} onChange={handleTabChange}>
            <Tab label="Đăng Nhập" />
            <Tab label="Đăng Ký" />
          </Tabs>

          <TabPanel value={tabValue} index={0}>
            <form onSubmit={handleLogin}>
              <TextField
                fullWidth
                label="Tên đăng nhập"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                margin="normal"
                required
              />
              <TextField
                fullWidth
                label="Mật khẩu"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                margin="normal"
                required
              />
              <Button
                type="submit"
                variant="contained"
                color="primary"
                fullWidth
                sx={{ mt: 2 }}
              >
                Đăng Nhập
              </Button>
            </form>
          </TabPanel>

          <TabPanel value={tabValue} index={1}>
            <form onSubmit={handleRegister}>
              <TextField
                fullWidth
                label="Tên đăng nhập"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                margin="normal"
                required
              />
              <TextField
                fullWidth
                label="Mật khẩu"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                margin="normal"
                required
              />
              <Button
                type="submit"
                variant="contained"
                color="primary"
                fullWidth
                sx={{ mt: 2 }}
              >
                Đăng Ký
              </Button>
            </form>
          </TabPanel>
        </>
      )}
    </Paper>
  );
}

export default Login;
